import{_ as a,o as t,c as o,ah as r}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Guide — Partner","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/partenaire.md","filePath":"src/en/guide/partenaire.md"}'),n={name:"en/guide/partenaire.md"};function i(s,e,c,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="guide-—-partner" tabindex="-1">Guide — Partner <a class="header-anchor" href="#guide-—-partner" aria-label="Permalink to &quot;Guide — Partner&quot;">​</a></h1><p>Carry out your tasks and track your compensation.</p><h2 id="welcome-to-naia" tabindex="-1">Welcome to Naia <a class="header-anchor" href="#welcome-to-naia" aria-label="Permalink to &quot;Welcome to Naia&quot;">​</a></h2><p>You&#39;ve been invited by a project manager to work on one or more projects, with access limited to the tasks that concern you — you don&#39;t see the whole project the way a client or project manager would.</p><h2 id="your-tasks" tabindex="-1">Your tasks <a class="header-anchor" href="#your-tasks" aria-label="Permalink to &quot;Your tasks&quot;">​</a></h2><p>Your dashboard and each project&#39;s <strong>Tasks</strong> tab bring together the work assigned to you:</p><ul><li>view the tasks and specifications that concern you, across every project;</li><li>update their progress (to do, in progress, done) and upload your deliverables directly from their page.</li></ul><h2 id="your-compensation" tabindex="-1">Your compensation <a class="header-anchor" href="#your-compensation" aria-label="Permalink to &quot;Your compensation&quot;">​</a></h2><p>The terms of your compensation (flat fee, percentage of a milestone, or daily rate) are agreed with the project manager for each project — refer to your service agreement for the details.</p><ul><li>Submit your own invoice for the agreed compensation from the <strong>Partner payments</strong> tab of the relevant project.</li><li>Track your payment status (due or paid) directly from that tab — the administrator records the payment once it&#39;s been made.</li></ul><h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><p>Talk with the internal team via built-in messaging or task comments. You&#39;re notified of approvals, feedback, or new deadlines.</p><div class="warning custom-block"><p class="custom-block-title">Project blocked for non-payment</p><p>If a project is blocked because of a client&#39;s unpaid invoice, you&#39;re notified. You can finish a task you&#39;ve already started, but not start a new one until the project is unblocked. You keep access to the project, your documents and messaging.</p></div>',13)])])}const h=a(n,[["render",i]]);export{m as __pageData,h as default};
